import re, numpy as np

def user_texts(fname):
 out=[]
 for e in [json.loads(x) for x in (sess/fname).read_text().splitlines()]:
  if e.get('type')=='message' and e.get('message',{}).get('role')=='user':
   c=e['message'].get('content'); tx=' '.join(i.get('text','') for i in c if i.get('type')=='text') if isinstance(c,list) else str(c)
   out.append(tx)
 return out

def extract_pairs(fname):
 pairs=[]
 for tx in user_texts(fname):
  for m in re.finditer(r'Demo pair (\d+) input \((\d+)x(\d+)\):\n(.*?)(?=\nDemo pair \d+ output)', tx, re.S):
   n,h,w,ins=m.groups(); 
   out_m=re.search(r'Demo pair '+n+r' output \('+h+r'x'+w+r'\):\n(.*?)(?=\n\nSame instance|\nSame instance)',tx,re.S)
   if out_m:
    def grid(s): return np.array([[int(x) for x in line.strip().split()] for line in s.strip().splitlines() if line.strip()])
    pairs.append((int(n),grid(ins),grid(out_m.group(1))))
 return pairs
