from collections import deque

def comps(grid,bg,conn=8):
 h,w=grid.shape; vis=np.zeros((h,w),bool); cc=[]
 dirs=[(dr,dc) for dr in (-1,0,1) for dc in (-1,0,1) if (dr or dc) and (conn==8 or abs(dr)+abs(dc)==1)]
 for r in range(h):
  for c in range(w):
   if vis[r,c] or grid[r,c]==bg: continue
   col=grid[r,c]; q=[(r,c)]; vis[r,c]=True; pts=[]
   while q:
    x,y=q.pop(); pts.append((x,y))
    for dr,dc in dirs:
     nx,ny=x+dr,y+dc
     if 0<=nx<h and 0<=ny<w and not vis[nx,ny] and grid[nx,ny]==col:
      vis[nx,ny]=1;q.append((nx,ny))
   cc.append((col,pts))
 return cc

def norm(pts):
 r0=min(r for r,c in pts); c0=min(c for r,c in pts)
 return frozenset((r-r0,c-c0) for r,c in pts)

def match_comps(a,b):
 bg=Counter(a.flatten()).most_common(1)[0][0]
 ca=comps(a,bg,8); cb=comps(b,bg,8)
 entries=[]
 # match by col, normalized geometry exact
 for col,pts in ca:
  sh=norm(pts)
  matches=[p for co,p in cb if co==col and norm(p)==sh]
  if len(matches)==1:
   op=matches[0]
   entries.append((col,pts,op,(min(r for r,c in pts),min(c for r,c in pts)),(min(r for r,c in op),min(c for r,c in op))))
  else:
   entries.append((col,pts,None,None,None))
 return entries

for pair in p710+p705:
