 print('\nDemo',n,a.shape)
 for col,pts,op,src,dst in match_comps(a,b):
  print(col,len(pts),src,dst,'shift',tuple(dst[i]-src[i] for i in range(2)) if dst else None,'shape',sorted(norm(pts)))

